jQuery(function($){"use strict";window.sooGiftCards={init:function(){if(typeof sooGiftCardsOptions==="undefined"){console.log("Gift Cards Option not loaded correctly");return}this.initSettings();return},initSettings:function(){$(document).on("cloverGiftCardError",this.onGiftCardError);this.createElements()},onGiftCardError:function(e,result){console.log(e);console.log(result);window.cloverGiftCardIsValid=result?.GIFT_CARD_ELEMENTS?.isFormValid;console.log(window.cloverGiftCardIsValid)},formatPrice:function(priceInCentes){var p=priceInCentes/100;p=p.toFixed(2);return p.toString().replace(/(\d)(?=(\d{3})+(?!\d))/g,"$1,")},showInfoMessage:function(message,isError=true){this.hideInfoMessage();let elm=document.querySelector("#moo-cloverGiftCardPanel > div.moo-row.giftCardsSection div.giftCard-error > .clover-error");elm.textContent=message;if(isError){elm.style.color="red"}else{elm.style.color="green"}},hideInfoMessage:function(){this.finishCheckingBalance();let elm=document.querySelector("#moo-cloverGiftCardPanel > div.moo-row.giftCardsSection div.giftCard-error > .clover-error");elm.textContent=""},createElements:function(){const giftCardStyles={input:{"border-radius":"5px",height:"45px",padding:"10px",color:"#31325F",border:"1px solid #ccc","::placeholder":{color:"#CFD7E0"}},body:{margin:"0;",border:"0.7px solid #B8B8B8FF;","border-radius":"10px;",padding:"10px;",width:"96%;","overflow-x":" hidden;"},".fieldError input":{"border-color":"red",color:"red"},".errorMessage":{color:"red","min-height":"10px;"},".sectionHeader":{display:"none"}};window.clover_giftCard=window.elements.create("GIFT_CARD_ELEMENTS",giftCardStyles);window.clover_giftCard.addEventListener("change",event=>{this.onGiftCardChange(event);$(document.body).trigger("cloverGiftCardError",event)});this.mountElements()},mountElements:function(){console.log($("#moo_CloverGiftCard").length);if($("#moo_CloverGiftCard").length){window.clover_giftCard.mount("#moo_CloverGiftCard")}},onGiftCardChange:function(e){this.hideInfoMessage()},clickOnCheckBalance:function(){this.hideInfoMessage();this.startCheckingBalance();if(window.cloverGiftCardIsValid){try{const timeoutId=setTimeout(()=>{this.showInfoMessage("Please verify the gift card information",true)},5e3);window.clover.createGiftCardToken().then(response=>{clearTimeout(timeoutId);if(response.token){this.getBalance(response.token).then(response=>{if(!response.ok){throw new Error("Gift Card not valid, try again")}return response.json()}).then(data=>{if(typeof data.new_balance==="undefined"){throw new Error("Gift Card not valid, try again")}const message="Your balance is $"+this.formatPrice(data.new_balance);this.showInfoMessage(message,false)}).catch(error=>{this.showInfoMessage(error.message,true)})}else{this.showInfoMessage("Please verify the gift card information",true);return false}}).catch(err=>{console.log("catched");console.log(err)})}catch(err){console.log(err)}}else{this.showInfoMessage("Please verify the gift card information",true);return false}},startCheckingBalance:function(){let button=$(".giftCardsSection .bottom-section .sendButton .primaryButtonInput");button.html('<div class="dot-flashing"></div>');setTimeout(()=>{button.text(button.attr("aria-label"))},3e4)},finishCheckingBalance:function(){let button=$(".giftCardsSection .bottom-section .sendButton .primaryButtonInput");button.text(button.attr("aria-label"))},getBalance:function(token){return fetch(sooGiftCardsOptions.restApiUrl+"moo-clover/v1/gift-cards/balance",{method:"POST",mode:"cors",cache:"no-cache",credentials:"same-origin",headers:{"Content-Type":"application/json"},redirect:"follow",referrerPolicy:"no-referrer",body:JSON.stringify({source:token})})}};$(document).ready(function(){if(sooGiftCardsOptions.pakmsKey){try{window.clover=new Clover(sooGiftCardsOptions.pakmsKey,{locale:sooGiftCardsOptions.locale});window.elements=window.clover.elements();window.cloverGiftCardIsValid=false;window.sooGiftCards.init()}catch(error){console.log(error)}}})});